// ── Mover Card para IA no Helena ─────────────────────────────────────
// Após agendamento confirmado no Clinicorp, localiza o card do paciente
// no painel Helena (Meta ou Orgânico) e move para 'Agendado pela IA'.

const BEARER  = 'pn_22zvaOtn9H6mmwNKktsuKd91F8UDdLnuu085N5bw';
const BASE    = 'https://api.wts.chat';
const IA_STEP = '096ecc8b-c84e-4f20-9df8-bc684c6dff45';
const PANELS  = [
  'fd4df083-7422-4171-9ee2-1c098e799798', // Meta
  '481c3384-26e5-4a9e-9235-eeccfd506ad5', // Orgânico
];
const HEADERS = { Authorization: `Bearer ${BEARER}` };

const telefone = $('Configuracao Unidades').first().json.telefone_limpo;

// 1. Buscar contato pelo telefone
let contactId = null;
try {
  const res = await $helpers.httpRequest({
    method:  'GET',
    url:     `${BASE}/core/v1/contact`,
    headers: HEADERS,
    qs:      { Phone: telefone, PageSize: 1 },
  });
  contactId = res.items?.[0]?.id ?? null;
} catch(e) {}

if (!contactId) {
  return [{ json: { status: 'contato_nao_encontrado', telefone } }];
}

// 2. Localizar card ativo em qualquer dos painéis
let cardId = null;
for (const panelId of PANELS) {
  try {
    const res = await $helpers.httpRequest({
      method:  'GET',
      url:     `${BASE}/crm/v1/panel/card`,
      headers: HEADERS,
      qs:      { PanelId: panelId, ContactId: contactId, PageSize: 10 },
    });
    const card = (res.items || []).find(c => !c.archived);
    if (card) { cardId = card.id; break; }
  } catch(e) {}
}

if (!cardId) {
  return [{ json: { status: 'card_nao_encontrado', contactId } }];
}

// 3. Mover para o step 'Agendado pela IA'
try {
  await $helpers.httpRequest({
    method:  'PUT',
    url:     `${BASE}/crm/v2/panel/card/${cardId}`,
    headers: { ...HEADERS, 'Content-Type': 'application/json' },
    body:    { fields: ['stepId'], stepId: IA_STEP },
  });
  return [{ json: { status: 'sucesso', cardId, stepMovido: IA_STEP } }];
} catch(e) {
  return [{ json: { status: 'erro_ao_mover', cardId, erro: e.message } }];
}
